INSERT INTO visa_types (code, name, category, family, official_name_id, permit_class, is_sold, price_keys, entry_type, sponsor, apply_channel, initial_stay_days, extendable, max_total_days, max_total_months, itap, law_card, source_url, page_sha256, retrieved_at, card_sha256, verification_status, valid_from, valid_until, superseded_by, stay_options)
VALUES (
    'E28A',
    'E28A Visa Investor',
    'KITAS/Limited Stay',
    'E28',
    'E28A Visa Investor',
    'ITAS',
    TRUE,
    $j$[{"category": "kitas_permits", "item_key": "Investor KITAS 2 Years (Altus/Onshore)"}, {"category": "kitas_permits", "item_key": "Investor KITAS 2 Years (Offshore)"}, {"category": "kitas_permits", "item_key": "Investor KITAS 2 Years (Extend)"}]$j$::jsonb,
    'MULTIPLE',
    'REQUIRED',
    NULL,
    NULL,
    TRUE,
    NULL,
    72,
    NULL,
    $j${"allowed_activities": "Berinvestasi, melakukan aktivitas yang berhubungan dengan bisnis, investasi, dan pendirian perusahaan. Anda juga diperkenankan untuk beraktivitas sebagai anggota direksi atau anggota dewan komisaris pada perusahaan tempat orang asing menanamkan modalnya. Selain itu anda diperbolehkan mengawasi proses produksi barang atau jasa di perusahaan yang didirikannya termasuk namun tidak terbatas pada kantor, pabrik, atau tempat sejenis lainnya. Anda dapat membawa serta keluarga tinggal di Indonesia. Visa ini juga memungkinkan Anda keluar-masuk Indonesia selama Izin Masuk Kembali masih berlaku. Anda diizinkan mengikuti pendidikan melalui mekanisme Rangkap Kegiatan Izin Tinggal. Anda juga diperkenankan melakukan aktivitas investasi, wisata, dan mengunjungi teman atau keluarga.", "code": "E28A", "dasar_hukum_verbatim": ["Undang-undang Nomor 6 tahun 2011 tentang Keimigrasian", "Peraturan Pemerintah Nomor 31 tahun 2013", "Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI", "Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal", "Peraturan Menteri Hukum dan HAM RI Nomor 22 tahun 2023 tentang Visa dan Izin Tinggal", "Keputusan Menteri Imigrasi dan Pemasyarakatan Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa", "Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI", "Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"], "definition_verbatim": "Berinvestasi, melakukan aktivitas yang berhubungan dengan bisnis, investasi, dan pendirian perusahaan. Anda juga diperkenankan untuk beraktivitas sebagai anggota direksi atau anggota dewan komisaris pada perusahaan tempat orang asing menanamkan modalnya. Selain itu anda diperbolehkan mengawasi proses produksi barang atau jasa di perusahaan yang didirikannya termasuk namun tidak terbatas pada kantor, pabrik, atau tempat sejenis lainnya. Anda dapat membawa serta keluarga tinggal di Indonesia. Visa ini juga memungkinkan Anda keluar-masuk Indonesia selama Izin Masuk Kembali masih berlaku. Anda diizinkan mengikuti pendidikan melalui mekanisme Rangkap Kegiatan Izin Tinggal. Anda juga diperkenankan melakukan aktivitas investasi, wisata, dan mengunjungi teman atau keluarga.", "entry": "multiple", "extendable": ["Izin Tinggal ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "Perpanjangan izin tinggal dapat dilakukan secara online oleh sponsor melalui akun yang telah terdaftar di evisa.imigrasi.go.id"], "http_status": 200, "itap_eligibility_as_stated_boolean": null, "itap_family_evidence": "ITAP.json", "itap_status": "TO_VERIFY", "itap_verbatim": [{"section": "Jenis visa", "text": "Izin Tinggal ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E28A"}], "jenis_visa_verbatim": "Visa ini merupakan Visa Tinggal Terbatas untuk masuk ke Indonesia yang memungkinkan Anda untuk masuk dan keluar Indonesia dalam jangka waktu tertentu. Izin Tinggal ini dapat diperpanjang dan dapat dialihkan menjadi izin tinggal lainnya.", "ketentuan_lain_verbatim": ["Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas (ITAS) dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi.", "Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal yang diberikan, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, kecuali diperlukan dalam pekerjaan tersebut."], "masa_tinggal_verbatim": "- Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun. Izin tinggal dihitung sejak tanggal kedatangan.\n- Perpanjangan izin tinggal dapat dilakukan secara online oleh sponsor melalui akun yang telah terdaftar di evisa.imigrasi.go.id", "notes": ["VERIFIED_FROM_SOURCE means faithful extraction, not resolution of legal inconsistencies. Whitespace and HTML list markers are normalized; source wording, spelling, punctuation and alternatives are retained.", "stay_days retains source year-based sentences; no conversion of years into days. entry=multiple derives only from the explicit entry/exit wording. where_to_apply is null: no explicit offshore/onshore rule is stated.", "Requirements are numbered in source order. Counts include parent bullets and alternative bullets; they are not a count of simultaneously mandatory documents. Scope labels and the full Persyaratan khusus text preserve conditional context. Reference directories are retained separately and excluded from the count.", "itap_verbatim includes generic/other-ITAS conversion wording requested by the brief. It is not a finding of ITAS-to-ITAP eligibility; the visa page does not explicitly name ITAP. Code-specific eligibility is null + TO_VERIFY; see ITAP.json.", "PNBP text is official reference only, never a client price.", "TO_VERIFY: initial-duration options on this visa page differ from the general official ITAS table; supplementary_stay_evidence retains that separate source. The visa-page values are not overwritten."], "official_name_id": "E28A Visa Investor", "page_sha256": "171b7ed2f6d6660905def426a49dee98d18f737c31a2b55ff07e118b21794f01", "pengajuan_intro_verbatim": "Anda harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa. Setelah memiliki akun, Anda dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "persyaratan_khusus_context_verbatim": null, "persyaratan_khusus_verbatim": "- Bukti kepemilikan saham paling sedikit Rp10.000.000.000,00 (sepuluh miliar rupiah) atau setara pada perusahaan penjamin yang terdaftar di Kementerian Investasi/Badan Koordinasi Penanaman Modal. Jika saham Anda kurang dari jumlah tersebut, dan Anda juga menduduki jabatan dalam perusahaan (direksi atau komisaris), maka Anda harus mengajukan visa bekerja sesuai dengan jabatan yang anda duduki.\n- Keputusan Kementerian Hukum dan Hak Asasi Manusia tentang pengesahan pendirian perusahaan\n- Rekening giro perusahaan 2 (dua) bulan terakhir. Jika perusahaan didirikan kurang dari 2 bulan, persyaratan rekening koran tersebut dapat disampaikan ke kantor imigrasi paling lama 90 hari setelah ITAS terbit.", "pnbp_verbatim_for_reference_only": ["Masa tinggal 1 tahun : Rp. 7.000.000,-", "Komponen Biaya:", "- Biaya visa Rp 500.000", "- Izin tinggal terbatas Rp 3.000.000", "- Izin masuk kembali Rp 1.500.000", "- Biaya Verifikasi II Rp 2.000.000", "Masa tinggal 2 tahun Rp9.500.000", "Komponen Biaya:", "• Visa Tinggal Terbatas: Rp500.000", "• Biaya Verifikasi Visa Kategori II: Rp2.000.000", "• Izin Tinggal Terbatas paling lama 2 tahun: Rp5.000.000", "• Izin Masuk Kembali paling lama 2 tahun: Rp2.000.000", "Semua pembayaran (PNBP) dapat dilakukan melalui beberapa bank yang telah ditunjuk. Silakan lihat kode billing yang muncul di sistem setelah pengajuan visa oleh sponsor."], "prohibited_or_conditions_verbatim": ["Anda dilarang tinggal di wilayah Indonesia melebihi jangka waktu izin tinggal yang diberikan, melakukan pekerjaan yang tidak sesuai dengan izin tinggal, melakukan penjualan barang atau jasa, kecuali diperlukan dalam pekerjaan tersebut."], "proses_pengajuan_verbatim": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\n- pemeriksaan kelengkapan persyaratan;\n- verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\n- pembuatan profil dan verifikasi;\n- persetujuan;\n- penerbitan visa.\nWaktu Proses lima hari kerja setelah pembayaran visa diterima.", "raw_path": "raw/E28A.html", "reference_lists_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "surat permohonan penerbitan visa"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin sebesar minimal USD2000 atau dalam mata uang lain yang setara jumlahnya,"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "daftar riwayat hidup (CV)"}, {"n": 6, "section": "Pengajuan visa (berkas elektronik)", "text": "rincian perjalanan (itinerary)"}, {"n": 7, "section": "Persyaratan Khusus", "text": "Bukti kepemilikan saham paling sedikit Rp10.000.000.000,00 (sepuluh miliar rupiah) atau setara pada perusahaan penjamin yang terdaftar di Kementerian Investasi/Badan Koordinasi Penanaman Modal. Jika saham Anda kurang dari jumlah tersebut, dan Anda juga menduduki jabatan dalam perusahaan (direksi atau komisaris), maka Anda harus mengajukan visa bekerja sesuai dengan jabatan yang anda duduki."}, {"n": 8, "section": "Persyaratan Khusus", "text": "Keputusan Kementerian Hukum dan Hak Asasi Manusia tentang pengesahan pendirian perusahaan"}, {"n": 9, "section": "Persyaratan Khusus", "text": "Rekening giro perusahaan 2 (dua) bulan terakhir. Jika perusahaan didirikan kurang dari 2 bulan, persyaratan rekening koran tersebut dapat disampaikan ke kantor imigrasi paling lama 90 hari setelah ITAS terbit."}], "retrieved_at": "2026-10-17T13:27:11Z", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E28A", "sponsor_required": {"as_stated_boolean": true, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda membutuhkan penjamin/sponsor untuk mengajukan visa ini."]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Anda dapat memilih untuk tinggal di Indonesia selama 1 tahun atau 2 tahun."], "supplementary_stay_evidence": {"code_name_verbatim": "Visa Tinggal Terbatas untuk Penanaman Modal Asing (E28A)", "extension_verbatim": "Dapat diberikan perpanjangan ITAS untuk jangka waktu tidak melebihi jangka waktu pemberian ITAS pertama dengan ketentuan keseluruhan ITAS tidak lebih dari 6 tahun.", "initial_stay_verbatim": "2 tahun", "page_sha256": "e429a98710f6743ee94c717f4b29a686044bc49bcd11718c7c2e8db1f041d28e", "raw_path": "raw/ITAP-central-detail.html", "retrieved_at": "2026-10-17T13:27:38Z", "scope": "ITAS duration/extension table; not an ITAP conversion entitlement.", "source_url": "https://www.imigrasi.go.id/wna/izin-tinggal-keimigrasian/izin-tinggal-tetap"}, "to_verify": ["itap_eligibility_as_stated_boolean", "where_to_apply", "total_max_stay_verbatim", "visa_page_vs_general_table_initial_duration"], "total_max_stay_verbatim": null, "where_to_apply": null}$j$::jsonb,
