VALUES (
    'E28F',
    'E28F Visa Investor Pendirian Cabang atau Anak Perusahaan di Ibu Kota Nusantara',
    'KITAS/Limited Stay',
    'E28',
    'E28F Visa Investor Pendirian Cabang atau Anak Perusahaan di Ibu Kota Nusantara',
    'ITAS',
    NULL,
    $j$[]$j$::jsonb,
    'MULTIPLE',
    'NOT_REQUIRED',
    NULL,
    NULL,
    TRUE,
    NULL,
    120,
    NULL,
    $j${"allowed_activities": "Dengan visa ini, Anda dapat berinvestasi, melakukan aktivitas yang berhubungan dengan bisnis, investasi, dan pendirian perusahaan, termasuk melakukan pembahasan, negosiasi, dan/atau menandatangani perjanjian bisnis.\nAnda juga diperkenankan untuk beraktivitas sebagai anggota direksi atau anggota dewan komisaris pada perusahaan tempat orang asing menanamkan modalnya. Selain itu, Anda diperbolehkan mengawasi proses produksi barang atau jasa di perusahaan yang didirikannya, termasuk namun tidak terbatas pada kantor, pabrik, atau tempat sejenis lainnya.\nAnda dapat membawa keluarga Anda untuk tinggal di Indonesia. Visa ini juga memungkinkan Anda keluar-masuk Indonesia selama Izin Masuk Kembali masih berlaku. Anda juga diperkenankan melakukan aktivitas wisata, pembelian barang, serta mengunjungi teman atau keluarga.\nAnda juga diperkenankan menerima imbalan atau fasilitas atas investasi yang Anda tanamkan dan/atau jabatan yang Anda pegang.", "code": "E28F", "dasar_hukum_verbatim": ["Peraturan Pemerintah Nomor 45 tahun 2024 tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM RI tentang Tarif PNBP di Lingkungan Kementerian Hukum dan HAM", "Peraturan Menteri Hukum dan HAM RI Nomor 22 Tahun 2023 tentang Visa dan Izin Tinggal", "Peraturan Menteri Hukum dan HAM RI Nomor 11 Tahun 2024 tentang Visa dan Izin Tinggal", "Keputusan Menteri Imigrasi dan Pemasyarakatan RI Nomor M.IP-08.GR.01.01 tahun 2025 tentang Klasifikasi Visa", "Peraturan Menteri Keuangan RI Nomor 9/PMK.02/2022 tentang Jenis dan Tarif PNBP Kebutuhan Mendesak atas Pelayanan Keimigrasian yang berlaku pada Kemenkumham RI", "Peraturan Menteri Keuangan RI Nomor 82 Tahun 2023 tentang Jenis dan Tarif atas Jenis PNBP Kebutuhan Mendesak atas Pelayanan Golden Visa yang berlaku pada Kemenkumham RI"], "definition_verbatim": "Visa investor ini dapat diajukan oleh orang asing dari negara mana pun yang memenuhi syarat untuk berinvestasi di Indonesia.\nVisa ini diperuntukkan bagi orang asing yang akan menjabat sebagai anggota direksi atau anggota dewan komisaris pada perusahaan yang akan didirikan di Ibu Kota Nusantara, yang merupakan cabang atau anak perusahaan dari perusahaan di luar wilayah Indonesia, dengan masa tinggal yang dapat mencapai 5 (lima) atau 10 (sepuluh) tahun.", "entry": "multiple", "extendable": ["Ekstensi : Dapat diperpanjang."], "http_status": 200, "itap_eligibility_as_stated_boolean": null, "itap_family_evidence": "ITAP.json", "itap_status": "TO_VERIFY", "itap_verbatim": [{"section": "Ringkasan visa", "text": "Alih status : Dapat dialihstatuskan ke izin tinggal terbatas lain.", "url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E28F"}], "jenis_visa_verbatim": "Jenis visa : Visa tinggal terbatas bagi orang asing yang akan menjabat sebagai anggota direksi atau anggota dewan komisaris pada perusahaan yang akan didirikan di Ibu Kota Nusantara, yang merupakan cabang atau anak perusahaan dari perusahaan di luar wilayah Indonesia.", "ketentuan_lain_verbatim": ["Orang Asing tanpa kewarganegaraan dan Orang Asing pemegang dokumen perjalanan (bukan paspor kebangsaan) berupa paspor sementara, paspor darurat, titre du voyage, certificate of identity, laissez passer, atau dokumen sejenis lainnya harus melampirkan dokumen Izin Masuk Kembali ke negara tempat Visa Kunjungan diajukan serta tiket kembali/tiket terusan ke negara lain (kecuali bagi awak alat angkut).", "Masa berlaku visa adalah 90 hari sejak diterbitkan. Jika tidak digunakan setelah jangka waktu tersebut, Orang Asing harus mengajukan visa baru untuk dapat masuk ke Indonesia.", "Harap diperhatikan bahwa masa berlaku visa berbeda dengan masa tinggal, silakan periksa visa Anda untuk informasi tentang lama izin tinggal.", "Izin Tinggal Terbatas (ITAS) dan Izin Masuk Kembali akan terbit secara otomatis begitu Anda diizinkan masuk oleh petugas pada Tempat Pemeriksaan Imigrasi."], "masa_tinggal_verbatim": null, "notes": ["VERIFIED_FROM_SOURCE means faithful extraction, not resolution of legal inconsistencies. Whitespace and HTML list markers are normalized; source wording, spelling, punctuation and alternatives are retained.", "stay_days retains source year-based sentences; no conversion of years into days. entry=multiple derives only from the explicit entry/exit wording. where_to_apply is null: no explicit offshore/onshore rule is stated.", "Requirements are numbered in source order. Counts include parent bullets and alternative bullets; they are not a count of simultaneously mandatory documents. Scope labels and the full Persyaratan khusus text preserve conditional context. Reference directories are retained separately and excluded from the count.", "itap_verbatim includes generic/other-ITAS conversion wording requested by the brief. It is not a finding of ITAS-to-ITAP eligibility; the visa page does not explicitly name ITAP. Code-specific eligibility is null + TO_VERIFY; see ITAP.json.", "PNBP text is official reference only, never a client price.", "TO_VERIFY: application requires Paspor kebangsaan, while Ketentuan lain includes a stateless/non-national-travel-document clause. Both source statements are retained without deciding document eligibility."], "official_name_id": "E28F Visa Investor Pendirian Cabang atau Anak Perusahaan di Ibu Kota Nusantara", "page_sha256": "2030e0f82921fa03b9bb0485e2dcfd4dd18778493987ddaad60331b8859f99c5", "pengajuan_intro_verbatim": "Anda harus memiliki akun di evisa.imigrasi.go.id sebelum mengajukan visa. Setelah memiliki akun, Anda dapat mengajukan visa setelah login di evisa.imigrasi.go.id dengan menyiapkan berkas elektronik (detail format file) Orang Asing antara lain:", "persyaratan_khusus_context_verbatim": null, "persyaratan_khusus_verbatim": "Visa 5 tahun\n- Pernyataan komitmen bahwa perusahaan asing akan menanamkan investasi paling sedikit US$5.000.000, untuk jangka waktu tinggal sampai dengan 5 tahun yang harus dipenuhi dalam waktu 90 hari terhitung sejak tanggal masuk ke Indonesia.\nVisa 10 tahun\n- Pernyataan komitmen bahwa perusahaan asing akan menanamkan investasi paling sedikit US$10.000.000, untuk jangka waktu tinggal sampai dengan 10 tahun yang harus dipenuhi dalam waktu 90 hari terhitung sejak tanggal masuk ke Indonesia.", "pnbp_verbatim_for_reference_only": ["Masa tinggal hingga 5 tahun: Rp13.000.000", "Komponen biaya", "- Biaya Izin Tinggal: Rp7.000.000", "- Biaya Visa Tinggal : Rp500.000", "- Biaya Verifikasi II: Rp2.000.000", "- Biaya Izin Masuk Kembali: Rp3.500.000", "Masa tinggal hingga 10 tahun : Rp. 19.500.000", "Komponen biaya", "- Biaya Izin Tinggal: Rp12.000.000", "- Biaya Visa Tinggal : Rp500.000", "- Biaya Verifikasi II: Rp2.000.000", "- Biaya Izin Masuk Kembali: Rp5.000.000"], "prohibited_or_conditions_verbatim": ["Tinggal di wilayah Indonesia melebihi masa berlaku izin tinggal.", "Melakukan pekerjaan yang tidak sesuai dengan jenis izin tinggal.", "Melakukan kegiatan yang tidak sesuai dengan uraian kegiatan dan hak yang diberikan, kecuali telah mengajukan perubahan atau pengajuan rangkap jenis kegiatan."], "proses_pengajuan_verbatim": "Pengajuan Visa di Direktorat Jenderal Imigrasi:\n- pemeriksaan kelengkapan persyaratan;\n- verifikasi pembayaran biaya imigrasi sesuai dengan ketentuan peraturan perundang-undangan;\n- pembuatan profil dan verifikasi;\n- persetujuan;\n- penerbitan visa.\nWaktu Proses lima hari kerja setelah pembayaran visa diterima.", "raw_path": "raw/E28F.html", "reference_lists_verbatim": null, "requirements_verbatim": [{"n": 1, "section": "Pengajuan visa (berkas elektronik)", "text": "Paspor kebangsaan yang sah dan masih berlaku paling singkat 6 bulan sebelum masa berlakunya habis,"}, {"n": 2, "section": "Pengajuan visa (berkas elektronik)", "text": "bukti memiliki biaya hidup selama berada di wilayah Indonesia berupa rekening koran 3 bulan terakhir atas nama Orang Asing atau penjamin sebesar minimal US$2.000 atau dalam mata uang lain yang setara jumlahnya,"}, {"n": 3, "section": "Pengajuan visa (berkas elektronik)", "text": "pasfoto berwarna terbaru (setahun terakhir). Detail"}, {"n": 4, "section": "Pengajuan visa (berkas elektronik)", "text": "daftar riwayat hidup (CV)"}, {"n": 5, "section": "Pengajuan visa (berkas elektronik)", "text": "rincian perjalanan (itinerary)"}, {"n": 6, "section": "Persyaratan Khusus / Visa 5 tahun", "text": "Pernyataan komitmen bahwa perusahaan asing akan menanamkan investasi paling sedikit US$5.000.000, untuk jangka waktu tinggal sampai dengan 5 tahun yang harus dipenuhi dalam waktu 90 hari terhitung sejak tanggal masuk ke Indonesia."}, {"n": 7, "section": "Persyaratan Khusus / Visa 10 tahun", "text": "Pernyataan komitmen bahwa perusahaan asing akan menanamkan investasi paling sedikit US$10.000.000, untuk jangka waktu tinggal sampai dengan 10 tahun yang harus dipenuhi dalam waktu 90 hari terhitung sejak tanggal masuk ke Indonesia."}], "retrieved_at": "2026-10-17T13:27:12Z", "ringkasan_visa_verbatim": "Jenis visa : Visa tinggal terbatas bagi orang asing yang akan menjabat sebagai anggota direksi atau anggota dewan komisaris pada perusahaan yang akan didirikan di Ibu Kota Nusantara, yang merupakan cabang atau anak perusahaan dari perusahaan di luar wilayah Indonesia.\nMasa tinggal : 5 tahun dan 10 tahun.\nEkstensi : Dapat diperpanjang.\nAlih status : Dapat dialihstatuskan ke izin tinggal terbatas lain.", "source_url": "https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E28F", "sponsor_required": {"as_stated_boolean": false, "invitation_requirement_see": "requirements_verbatim (Persyaratan Khusus)", "verbatim": ["Anda tidak membutuhkan penjamin/sponsor untuk mengajukan visa ini"]}, "status": "VERIFIED_FROM_SOURCE", "stay_days": ["Masa tinggal : 5 tahun dan 10 tahun."], "supplementary_stay_evidence": {"code_name_verbatim": "Visa Tinggal Terbatas sebagai Penanam Modal Asing yang Menjabat Direksi atau Komisaris di Anak/Cabang Perusahaan dalam Ibu Kota Nusantara (E28F)", "extension_verbatim": "Orang Asing dengan Izin Tinggal pertama paling singkat 5 tahun dapat diberikan perpanjangan Izin Tinggal Terbatas untuk jangka waktu tidak melebihi jangka waktu pemberian Izin Tinggal Terbatas pertama dengan ketentuan keseluruhan Izin Tinggal Terbatas tidak lebih dari 10 tahun.", "initial_stay_verbatim": "5 tahun\n10 tahun", "page_sha256": "e429a98710f6743ee94c717f4b29a686044bc49bcd11718c7c2e8db1f041d28e", "raw_path": "raw/ITAP-central-detail.html", "retrieved_at": "2026-10-17T13:27:38Z", "scope": "ITAS duration/extension table; not an ITAP conversion entitlement.", "source_url": "https://www.imigrasi.go.id/wna/izin-tinggal-keimigrasian/izin-tinggal-tetap"}, "to_verify": ["itap_eligibility_as_stated_boolean", "where_to_apply", "total_max_stay_verbatim", "national_passport_requirement_vs_non_national_document_clause"], "total_max_stay_verbatim": null, "where_to_apply": null}$j$::jsonb,
    'https://www.imigrasi.go.id/wna/daftar-visa-indonesia/E28F',
